refentry.refsect1:
&reftitle.errors;


 Lanza una excepción PharException si ocurren errores
 durante la escritura en el disco.

  &reftitle.examples;



    Ejemplo con Phar::extractTo


<?php
try {
    $phar = new Phar('myphar.phar');
    $phar->extractTo('/full/path'); // extrae todos los ficheros
    $phar->extractTo('/another/path', 'file.txt'); // extrae solo file.txt
    $phar->extractTo('/this/path',
        array('file1.txt', 'file2.txt')); // extrae solo 2 ficheros
    $phar->extractTo('/third/path', null, true); // extrae todos los ficheros, sobrescribiendo
} catch (Exception $e) {
    // maneja los errores
}
?>
